// Input: 4 5 0 1 2 1 3 3 2 3 5 3 4 2 4 3 1 2 3 4
// Output: 0 1 2 3 2 0 1 2 3 1 0 1 4 2 1 0

// Floyd-Warshall 多源最短路算法
// 该程序实现了经典的 Floyd-Warshall 算法，用于计算图中所有顶点对之间的最短路径
// 包含：多维数组、嵌套循环、递归、函数传参、条件判断等语法

// 获取最小值
int min(int a, int b) {
    if (a < b) {
        return a;
    } else {
        return b;
    }
}

// 获取最大值
int max(int a, int b) {
    if (a > b) {
        return a;
    } else {
        return b;
    }
}

// 初始化图
void initGraph(int n, int graph[][100]) {
    int i;
    int j;

    i = 0;
    while (i < n) {
        j = 0;
        while (j < n) {
            if (i == j) {
                graph[i][j] = 0;
            } else {
                graph[i][j] = 999999;  // 无穷大
            }
            j = j + 1;
        }
        i = i + 1;
    }
}

// 打印图
void printGraph(int n, int graph[][100]) {
    int i;
    int j;

    i = 0;
    while (i < n) {
        j = 0;
        while (j < n) {
            write(graph[i][j]);
            j = j + 1;
        }
        i = i + 1;
    }
}

// 打印一维数组
void printArray(int n, int arr[]) {
    int i;
    i = 0;
    while (i < n) {
        write(arr[i]);
        i = i + 1;
    }
}

// Floyd-Warshall 算法核心
void floydWarshall(int n, int graph[][100]) {
    int i;
    int j;
    int k;
    int temp;

    // 三重循环实现动态规划
    k = 0;
    while (k < n) {
        i = 0;
        while (i < n) {
            j = 0;
            while (j < n) {
                // 如果经过 k 点的路径更短，则更新
                temp = graph[i][k] + graph[k][j];
                if (temp < graph[i][j]) {
                    graph[i][j] = temp;
                }
                j = j + 1;
            }
            i = i + 1;
        }
        k = k + 1;
    }
}

// 检测负环（如果存在负环，对角线会有负值）
int hasNegativeCycle(int n, int graph[][100]) {
    int i;
    i = 0;
    while (i < n) {
        if (graph[i][i] < 0) {
            return 1;
        }
        i = i + 1;
    }
    return 0;
}

