    } else {
        return b;
    }
}

// 初始化图
void initGraph(int n, int graph[][100]) {
    int i;
    int j;

    i = 0;
    while (i < n) {
        j = 0;
        while (j < n) {
            if (i == j) {
                graph[i][j] = 0;
            } else {
                graph[i][j] = 999999;
            }
            j = j + 1;
        }
        i = i + 1;
    }
}

// Floyd-Warshall 算法核心 - 三重嵌套循环
void floydWarshall(int n, int graph[][100]) {
    int i;
    int j;
    int k;
    int temp;

    k = 0;
    while (k < n) {
        i = 0;
        while (i < n) {
            j = 0;
            while (j < n) {
                temp = graph[i][k] + graph[k][j];
                if (temp < graph[i][j]) {
                    graph[i][j] = temp;
                }
                j = j + 1;
            }
            i = i + 1;
        }
        k = k + 1;
    }
}

// 冒泡排序
void bubbleSort(int n, int arr[]) {
    int i;
    int j;
    int temp;

    i = 0;
    while (i < n - 1) {
        j = 0;
        while (j < n - i - 1) {
            if (arr[j] > arr[j + 1]) {
                temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
            j = j + 1;
        }
        i = i + 1;
    }
}

// 快速排序分区
int partition(int arr[], int low, int high) {
    int pivot;
    int i;
    int j;
    int temp;

    pivot = arr[high];
    i = low - 1;
    j = low;

    while (j < high) {
        if (arr[j] <= pivot) {
            i = i + 1;
            temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
        }
        j = j + 1;
    }

    temp = arr[i + 1];
    arr[i + 1] = arr[high];
    arr[high] = temp;

    return i + 1;
}

// 快速排序递归
void quickSortRec(int arr[], int low, int high) {
    int pi;

    if (low < high) {
        pi = partition(arr, low, high);
        quickSortRec(arr, low, pi - 1);
        quickSortRec(arr, pi + 1, high);
    }
}

// 快速排序 wrapper
void quickSort(int n, int arr[]) {
    quickSortRec(arr, 0, n - 1);
}

// 归并排序合并
void merge(int arr[], int left, int mid, int right) {
    int n1;
    int n2;
    int i;
    int j;
    int k;
