            } else {
                graph[i][j] = 999999;
            }
            j = j + 1;
        }
        i = i + 1;
    }
}

// Floyd-Warshall 算法核心 - 三重嵌套循环
void floydWarshall(int n, int graph[][100]) {
    int i;
    int j;
    int k;
    int temp;

    k = 0;
    while (k < n) {
        i = 0;
        while (i < n) {
            j = 0;
            while (j < n) {
                temp = graph[i][k] + graph[k][j];
                if (temp < graph[i][j]) {
                    graph[i][j] = temp;
                }
                j = j + 1;
            }
            i = i + 1;
        }
        k = k + 1;
    }
}

// 冒泡排序
void bubbleSort(int n, int arr[]) {
    int i;
    int j;
    int temp;

    i = 0;
    while (i < n - 1) {
        j = 0;
        while (j < n - i - 1) {
            if (arr[j] > arr[j + 1]) {
                temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
            j = j + 1;
        }
        i = i + 1;
    }
}

