    int i;
    int j;
    int temp;

    i = 0;
    while (i < n - 1) {
        j = 0;
        while (j < n - i - 1) {
            if (arr[j] > arr[j + 1]) {
                temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
            j = j + 1;
        }
        i = i + 1;
    }
}

// 快速排序分区
int partition(int arr[], int low, int high) {
    int pivot;
    int i;
    int j;
    int temp;

    pivot = arr[high];
    i = low - 1;
    j = low;

    while (j < high) {
        if (arr[j] <= pivot) {
            i = i + 1;
            temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
        }
        j = j + 1;
    }

    temp = arr[i + 1];
    arr[i + 1] = arr[high];
    arr[high] = temp;

    return i + 1;
}

// 快速排序递归
void quickSortRec(int arr[], int low, int high) {
    int pi;

    if (low < high) {
        pi = partition(arr, low, high);
        quickSortRec(arr, low, pi - 1);
        quickSortRec(arr, pi + 1, high);
    }
}

// 快速排序 wrapper
void quickSort(int n, int arr[]) {
    quickSortRec(arr, 0, n - 1);
}

// 归并排序合并
void merge(int arr[], int left, int mid, int right) {
    int n1;
    int n2;
    int i;
    int j;
    int k;
    int L[100];
    int R[100];

    n1 = mid - left + 1;
    n2 = right - mid;

    i = 0;
    while (i < n1) {
        L[i] = arr[left + i];
        i = i + 1;
    }

    i = 0;
    while (i < n2) {
        R[i] = arr[mid + 1 + i];
        i = i + 1;
    }

    L[n1] = 999999;
    R[n2] = 999999;

    i = 0;
    j = 0;
    k = left;

    while (k <= right) {
        if (L[i] <= R[j]) {
            arr[k] = L[i];
            i = i + 1;
        } else {
            arr[k] = R[j];
            j = j + 1;
        }
        k = k + 1;
    }
}

// 归并排序递归
void mergeSortRec(int arr[], int left, int right) {
    int mid;

    if (left < right) {
        mid = (left + right) / 2;
        mergeSortRec(arr, left, mid);
        mergeSortRec(arr, mid + 1, right);
        merge(arr, left, mid, right);
    }
}

// 归并排序 wrapper
void mergeSort(int n, int arr[]) {
    mergeSortRec(arr, 0, n - 1);
}

