int sumArray(int arr[], int n) {
    int i;
    int total;

    total = 0;
    i = 0;
    while (i < n) {
        total = total + arr[i];
        i = i + 1;
    }

    return total;
}

// 计算数组平均值
int avgArray(int arr[], int n) {
    int total;
    total = sumArray(arr, n);
    return total / n;
}

