    i = 1;
    while (i < n) {
        if (arr[i] < minVal) {
            minVal = arr[i];
        }
        i = i + 1;
    }

    return minVal;
}

// 二分查找
int binarySearch(int arr[], int n, int target) {
    int left;
    int right;
