        }
        i = i + 1;
    }
}

// Floyd-Warshall 算法核心 - 三重嵌套循环
void floydWarshall(int n, int graph[][100]) {
    int i;
    int j;
    int k;
    int temp;

    k = 0;
    while (k < n) {
        i = 0;
        while (i < n) {
            j = 0;
            while (j < n) {
                temp = graph[i][k] + graph[k][j];
                if (temp < graph[i][j]) {
                    graph[i][j] = temp;
                }
                j = j + 1;
            }
            i = i + 1;
        }
        k = k + 1;
    }
}

