int initArr1[3] = {1, 2, 3};
int initArr2[2][2] = {{1, 2}, {3, 4}};

// 获取最小值
int min(int a, int b) {
    if (a < b) {
        return a;
    } else {
        return b;
    }
}

// 获取最大值
int max(int a, int b) {
    if (a > b) {
        return a;
    } else {
        return b;
    }
}

// 初始化图
void initGraph(int n, int graph[]) {
    int i;
    int j;
    int idx;

    i = 0;
    while (i < n) {
        j = 0;
        while (j < n) {
            idx = i * 10 + j;
            if (i == j) {
                graph[idx] = 0;
            } else {
                graph[idx] = 100;
            }
            j = j + 1;
        }
        i = i + 1;
    }
}

// Floyd-Warshall 算法核心 - 三重嵌套循环
void floydWarshall(int n, int graph[]) {
    int i;
    int j;
    int k;
    int temp;
    int idx1;
    int idx2;
    int idx3;

    k = 0;
    while (k < n) {
        i = 0;
        while (i < n) {
            j = 0;
            while (j < n) {
                idx1 = i * 10 + j;
                idx2 = i * 10 + k;
                idx3 = k * 10 + j;
                temp = graph[idx2] + graph[idx3];
                if (temp < graph[idx1]) {
                    graph[idx1] = temp;
                }
                j = j + 1;
            }
            i = i + 1;
        }
        k = k + 1;
    }
}

// 测试二维数组参数语法
int sum2DArray(int arr[][10], int n) {
    int i;
    int j;
    int total;

    total = 0;
    i = 0;
    while (i < n) {
        j = 0;
        while (j < n) {
            total = total + arr[i][j];
            j = j + 1;
        }
        i = i + 1;
    }

    return total;
}

// 冒泡排序
void bubbleSort(int n, int arr[]) {
    int i;
    int j;
    int temp;

    i = 0;
    while (i < n - 1) {
        j = 0;
        while (j < n - i - 1) {
            if (arr[j] > arr[j + 1]) {
                temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
            j = j + 1;
        }
        i = i + 1;
    }
}

// 快速排序分区
int partition(int arr[], int low, int high) {
    int pivot;
    int i;
    int j;
    int temp;

    pivot = arr[high];
    i = low - 1;
    j = low;

    while (j < high) {
        if (arr[j] <= pivot) {
            i = i + 1;
            temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
        }
        j = j + 1;
    }

    temp = arr[i + 1];
    arr[i + 1] = arr[high];
    arr[high] = temp;

    return i + 1;
