    if (x < 0) {
        putchar('-');
        x = -x;
    }
    char *p = __buf + 18;
    while (x) {
        *--p = x % 10 + '0';
        x /= 10;
    }
    while (p < __buf + 19) {
        putchar(*p++);
    }
}

