// 快速排序分区
int partition(int arr[], int low, int high) {
    int pivot;
    int i;
    int j;
    int temp;

    pivot = arr[high];
    i = low - 1;
    j = low;

    while (j < high) {
        if (arr[j] <= pivot) {
            i = i + 1;
            temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
        }
        j = j + 1;
    }

    temp = arr[i + 1];
    arr[i + 1] = arr[high];
    arr[high] = temp;

    return i + 1;
}

